INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(39111, 'Leviticus 8:20', 'Leviticus', 8, 20, 'هغه پسه ټوټې ټوټې کړ او هغه یې د سر او پاتې ټوټو او وازګې سره وسوځول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus8_verse_20.mp3', '', 1761754199, 1761754199),
(39112, 'Leviticus 8:21', 'Leviticus', 8, 21, 'څنګه چې څښتن موسی ته امر کړی ؤ، هغه د نس دنننۍ برخې او پښې ووینځلې او ټول پسه یې د قربانۍ په ځای باندې وسوځاوه. دا یوه سوځېدونکې نذرانه وه چې بوی یې په څښتن باندې ښه ولګېده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus8_verse_21.mp3', '', 1761754199, 1761754199),
(39113, 'Leviticus 8:22', 'Leviticus', 8, 22, 'بیا موسی بل پسه راوست. دا پسه د کاهنانو د ټاکنې دپاره ؤ. هارون او د هغه زامنو خپل لاسونه د هغه په سر باندې کېښودل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus8_verse_22.mp3', '', 1761754199, 1761754199),
(39114, 'Leviticus 8:23', 'Leviticus', 8, 23, 'موسی پسه حلال کړ او د هغه لږه وینه یې واخیستله او د هارون د ښي غوږ په نرمۍ، د ښي لاس په غټې ګوتې او د ښي پښې په غټه ګوته یې وسولوله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus8_verse_23.mp3', '', 1761754199, 1761754199),
(39115, 'Leviticus 8:24', 'Leviticus', 8, 24, 'بیا یې د هارون زامن مخکې راوستل او د هغوی د ښي غوږونو په نرمیو، د ښي لاسونو په غټو ګوتو او د ښي پښو په غټو ګوتو یې لږه وینه وسولوله او پاتې وینه یې د قربانۍ د ځای په څلورو خواو باندې وشیندله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus8_verse_24.mp3', '', 1761754199, 1761754199),
(39116, 'Leviticus 8:25', 'Leviticus', 8, 25, 'هغه وازګه، لم، هغه ټوله وازګه چې په کولمو باندې پرته وي، د اینې ډېره ښه برخه، پښتورګي د وازګې سره چې ورباندې پرته وي او ښي ورون واخیستل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus8_verse_25.mp3', '', 1761754199, 1761754199),
(39117, 'Leviticus 8:26', 'Leviticus', 8, 26, 'بیا هغه د فطیرې ډوډۍ د ټوکرۍ څخه چې څښتن ته وقف شوې وه یوه ساده ډوډۍ، یوه غوړه ډوډۍ او یوه نرۍ ډوډۍ راواخیستله او د وازګې او ښي ورون دپاسه یې کېښودله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus8_verse_26.mp3', '', 1761754199, 1761754199),
(39118, 'Leviticus 8:27', 'Leviticus', 8, 27, 'موسی هغه ټول د هارون او د هغه د زامنو په لاسونو کې کېښودل او دوی هغه پورته ونیول، ترڅو دا وښایي چې هغه څښتن ته وقف شوي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus8_verse_27.mp3', '', 1761754199, 1761754199),
(39119, 'Leviticus 8:28', 'Leviticus', 8, 28, 'بیا موسی دا شیان د هغوی څخه بېرته واخیستل او هغه یې د ټاکنې د نذرانې په توګه د سوځېدونکې نذرانې سره د قربانۍ په ځای باندې وسوځول. د داسې نذرانې بوی په څښتن باندې ښه لګېده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus8_verse_28.mp3', '', 1761754199, 1761754199),
(39120, 'Leviticus 8:29', 'Leviticus', 8, 29, 'بیا موسی د پسه سینه راواخیستله او د څښتن په حضور کې یې پورته ونیوله، ترڅو دا وښایي چې هغه څښتن ته وقف شوې ده. دا د ټاکنې په پسه کې د موسی برخه وه. موسی دا ټول کارونه د څښتن د حکم سره سم سرته ورسول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus8_verse_29.mp3', '', 1761754199, 1761754199),
(39121, 'Leviticus 8:30', 'Leviticus', 8, 30, 'موسی لږ د مسح کولو تېل او لږه وینه چې د قربانۍ په ځای باندې پرته وه واخیستل او په هارون، د هغه په زامنو او د هغو په کالیو باندې یې وشیندل. په دې ډول یې هغوی او د هغوی کالي څښتن ته وقف کړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus8_verse_30.mp3', '', 1761754199, 1761754199),
(39122, 'Leviticus 8:31', 'Leviticus', 8, 31, 'موسی هارون او د هغه زامنو ته وویل: «لکه څنګه چې څښتن حکم کړی دی دا غوښه د سپېڅلې خېمې د دروازې په خوله کې پخه کړئ او هلته یې د هغې ډوډۍ سره چې د ټاکنې د نذرانې په ټوکرۍ کې ده، وخورئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus8_verse_31.mp3', '', 1761754199, 1761754199),
(39123, 'Leviticus 8:32', 'Leviticus', 8, 32, 'کومه غوښه یا ډوډۍ چې پاتې شي، نو هغه وسوځوئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus8_verse_32.mp3', '', 1761754199, 1761754199),
(39124, 'Leviticus 8:33', 'Leviticus', 8, 33, 'تاسو به اووه ورځې د خېمې د دروازې د خولې څخه نه ځئ، ترڅو پورې چې ستاسو د ټاکنې مراسم پوره شوي نه وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus8_verse_33.mp3', '', 1761754199, 1761754199),
(39125, 'Leviticus 8:34', 'Leviticus', 8, 34, 'مونږ چې نن کوم کار وکړ، څښتن د هغه د کولو حکم مونږ ته کړی ؤ، د دې په خاطر چې ستاسو د ګناه دپاره کفاره ادا کړو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus8_verse_34.mp3', '', 1761754199, 1761754199),
(39126, 'Leviticus 8:35', 'Leviticus', 8, 35, 'تاسو باید د سپېڅلې خېمې د دروازې په خوله کې اووه شپې او اووه ورځې پاتې شئ او هغه کار به کوئ چې څښتن یې امر کړی دی. که چېرې داسې ونه کړئ نو مړه به شئ، ځکه چې څښتن په ما باندې داسې امر کړی دی.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus8_verse_35.mp3', '', 1761754199, 1761754199),
(39127, 'Leviticus 8:36', 'Leviticus', 8, 36, 'نو هارون او د هغه زامنو ټول کارونه د څښتن د هغه حکم له مخې وکړل چې د موسی په وسیله یې کړی ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus8_verse_36.mp3', '', 1761754199, 1761754199),
(39128, 'Proverbs 3:1', 'Proverbs', 3, 1, 'ای زما زویه! زما تعلیم مه هېروه او زما حکمونه په خپل زړه کې ټینګ وساته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs3_verse_1.mp3', '', 1761754199, 1761754199),
(39129, 'Proverbs 3:2', 'Proverbs', 3, 2, 'ځکه دا به ستا د عمر ورځې او کلونه ډېر کړي او سوله او سلامتي به در په برخه کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs3_verse_2.mp3', '', 1761754199, 1761754199),
(39130, 'Proverbs 3:3', 'Proverbs', 3, 3, 'مینه او وفا د خپل ځانه مه لېرې کوه هغه د تل دپاره د خپلې غاړې هار کړه او د خپل زړه په تخته یې ولیکه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs3_verse_3.mp3', '', 1761754199, 1761754199),
(39131, 'Proverbs 3:4', 'Proverbs', 3, 4, 'نو بیا به ته د خدای او انسان په نظر کې نېک وګڼل شې او د یو هوښیار انسان په توګه وپېژندل شې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs3_verse_4.mp3', '', 1761754199, 1761754199),
(39132, 'Proverbs 3:5', 'Proverbs', 3, 5, 'په خپل ټول زړه په څښتن توکل کوه او په خپل عقل او پوهه تکیه مه کوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs3_verse_5.mp3', '', 1761754199, 1761754199),
(39133, 'Proverbs 3:6', 'Proverbs', 3, 6, 'په هر کار کې د هغه د حضور غوښتنه کوه نو هغه به ستا لارې هوارې کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs3_verse_6.mp3', '', 1761754199, 1761754199),
(39134, 'Proverbs 3:7', 'Proverbs', 3, 7, 'په خپل فکر ځان د حکمت خاوند مه ګڼه له څښتن څخه وېره کوه او له بدۍ نه مخ واړوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs3_verse_7.mp3', '', 1761754199, 1761754199),
(39135, 'Proverbs 3:8', 'Proverbs', 3, 8, 'نو په دې به ستا بدن تل روغ وي او ټول وجود به دې تازه شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs3_verse_8.mp3', '', 1761754199, 1761754199),
(39136, 'Proverbs 3:9', 'Proverbs', 3, 9, 'په خپلې شتمنۍ سره د څښتن عزت کوه او د خپل ټول فصل لومړنۍ مېوه ورکوه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs3_verse_9.mp3', '', 1761754199, 1761754199),
(39137, 'Proverbs 3:10', 'Proverbs', 3, 10, 'نو بیا به ستا ګودامونه له غلي دانې نه ډک شي او چاټۍ‌ګانې به دې د انګورو له شیرې څخه له خولې نه واوړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs3_verse_10.mp3', '', 1761754199, 1761754199),
(39138, 'Proverbs 3:11', 'Proverbs', 3, 11, 'نو ای زما زویه! د څښتن اصلاح ته په سپکه سترګه مه ګوره او کله چې تا رټي نو هېڅکله مه خفه کېږه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs3_verse_11.mp3', '', 1761754199, 1761754199),
(39139, 'Proverbs 3:12', 'Proverbs', 3, 12, 'ځکه څښتن چې له چا سره مینه کوي نو هغه ته سزا ورکوي لکه یو پلار ته چې کوم زوی منلی وي نو رټنه یې د محبت نښه ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs3_verse_12.mp3', '', 1761754199, 1761754199),
(39140, 'Proverbs 3:13', 'Proverbs', 3, 13, 'بختور دی هغه څوک چې حکمت حاصل کړي او هغه څوک چې پوهه پیدا کړي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs3_verse_13.mp3', '', 1761754199, 1761754199),
(39141, 'Proverbs 3:14', 'Proverbs', 3, 14, 'ځکه چې د هغې ثمره له سپینو زرو نه غوره ده او حاصل یې له سرو زرو نه ډېر زیات دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs3_verse_14.mp3', '', 1761754199, 1761754199),
(39142, 'Proverbs 3:15', 'Proverbs', 3, 15, 'هغه د لعلونو نه ډېر قیمتي دی چې له ارزښت سره یې ستا له خوښې هېڅ ګټه برابره نه ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs3_verse_15.mp3', '', 1761754199, 1761754199),
(39143, 'Proverbs 3:16', 'Proverbs', 3, 16, 'د هغې په یو لاس کې اوږد ژوند دی او په بل لاس کې یې دولت او عزت دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs3_verse_16.mp3', '', 1761754199, 1761754199),
(39144, 'Proverbs 3:17', 'Proverbs', 3, 17, 'لارې یې خوشحالوونکې دي او ټولې لارې یې د سولې او سلامتۍ دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs3_verse_17.mp3', '', 1761754199, 1761754199),
(39145, 'Proverbs 3:18', 'Proverbs', 3, 18, 'څوک چې هغې ته غېږ ورکوي نو د هغوی دپاره د ژوندانه ونه ده او بختور دي هغه څوک چې هغې ته ټینګه غاړه ورکوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs3_verse_18.mp3', '', 1761754199, 1761754199),
(39146, 'Proverbs 3:19', 'Proverbs', 3, 19, 'څښتن په خپل حکمت سره د ځمکې بنیاد کېښود او اسمانونه یې د خپلې پوهې په وسیله پیدا کړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs3_verse_19.mp3', '', 1761754199, 1761754199),
(39147, 'Proverbs 3:20', 'Proverbs', 3, 20, 'د هغه د علم په وسیله د ځمکې په تل کې د اوبو چینې روانیږي او له ورېځو نه یې باران او پرخه په ځمکه راوریږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs3_verse_20.mp3', '', 1761754199, 1761754199),
(39148, 'Proverbs 3:21', 'Proverbs', 3, 21, 'نو ای زما زویه! پوهه له خپله نظره مه لېرې کوه او په خپل ځان کې د حکمت او لیاقت ټینګه ساتنه کوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs3_verse_21.mp3', '', 1761754199, 1761754199),
(39149, 'Proverbs 3:22', 'Proverbs', 3, 22, 'دوی به ستا روح تازه ساتي او دا به ستا د غاړې د فضل هار وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs3_verse_22.mp3', '', 1761754199, 1761754199),
(39150, 'Proverbs 3:23', 'Proverbs', 3, 23, 'نو بیا به په ډاډه زړه په خپله لار روان شې او ستا پښه به په تیږه نه لګیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs3_verse_23.mp3', '', 1761754199, 1761754199),
(39151, 'Proverbs 3:24', 'Proverbs', 3, 24, 'کله چې ته ویده کېږې نو نه به وېرېږې او د څملاستو په وخت کې به په خواږه خوب ویده کېږې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs3_verse_24.mp3', '', 1761754199, 1761754199),
(39152, 'Proverbs 3:25', 'Proverbs', 3, 25, 'نو له ناڅاپي بلا نه مه وېرېږه کله چې په تا راشي او نه د هغه توفان له تباهۍ نه چې په بدکارانو راځي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs3_verse_25.mp3', '', 1761754199, 1761754199),
(39153, 'Proverbs 3:26', 'Proverbs', 3, 26, 'ځکه څښتن به تل ستا ساتونکی وي چې پښه دې په دام کې ونه نښلي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs3_verse_26.mp3', '', 1761754199, 1761754199),
(39154, 'Proverbs 3:27', 'Proverbs', 3, 27, 'ترڅو چې د نېکۍ کولو توان لرې نو د مسکینانو سره له مرستې نه ډډه مه کوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs3_verse_27.mp3', '', 1761754199, 1761754199),
(39155, 'Proverbs 3:28', 'Proverbs', 3, 28, 'کله چې څوک ستا نه څه وغواړي او ته یې ولرې نو ورته مه وایه چې نن لاړ شه او سبا راشه، بیا به یې درکړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs3_verse_28.mp3', '', 1761754199, 1761754199),
(39156, 'Proverbs 3:29', 'Proverbs', 3, 29, 'د خپل ګاونډي په خلاف د زیان رسولو اراده مه لره څوک چې ستا په خوا کې اوسیږي او په تا باور کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs3_verse_29.mp3', '', 1761754199, 1761754199),
(39157, 'Proverbs 3:30', 'Proverbs', 3, 30, 'ترڅو چې چا تاته زیان نه وي رسولی نو په هغه باندې بېځایه تور مه لګوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs3_verse_30.mp3', '', 1761754199, 1761754199),
(39158, 'Proverbs 3:31', 'Proverbs', 3, 31, 'د ظالم انسان سره بخیلي مه کوه او د هغه د لارې پیروي مه کوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs3_verse_31.mp3', '', 1761754199, 1761754199),
(39159, 'Proverbs 3:32', 'Proverbs', 3, 32, 'ځکه څښتن له هغه چا نه کرکه کوي چې په غلطه لار روان وي خو هغه د رښتینو خلکو سره د دوستۍ اړیکې لري.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs3_verse_32.mp3', '', 1761754199, 1761754199),
(39160, 'Proverbs 3:33', 'Proverbs', 3, 33, 'د څښتن لعنت د بدکاره انسان په کور باندې وریږي خو هغه د نېکو خلکو په کورنیو باندې برکت وروي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs3_verse_33.mp3', '', 1761754199, 1761754199),
(39161, 'Proverbs 3:34', 'Proverbs', 3, 34, 'هغه په ملنډو وهونکو خندا کوي خو په عاجزانو خپل فضل کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs3_verse_34.mp3', '', 1761754199, 1761754199),
(39162, 'Proverbs 3:35', 'Proverbs', 3, 35, 'د حکمت خاوندانو ته عزت په میراث کې رسیږي خو کم‌عقلان به د شرم سره مخامخ کیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs3_verse_35.mp3', '', 1761754199, 1761754199),
(39163, 'Psalms 69:1', 'Psalms', 69, 1, 'وژغوره ما وژغوره ای خدایه اوبه نژدې دي چې نفس مې وباسي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms69_verse_1.mp3', '', 1761754199, 1761754199),
(39164, 'Psalms 69:2', 'Psalms', 69, 2, 'ژورو خټو کې ډوبېږمه زه داسې ځای نشته چې زه ودرېږمه ژورو اوبو کې ننوتی یمه دې ته نژدې یم چې کړي ډوب مې څپې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms69_verse_2.mp3', '', 1761754199, 1761754199),
(39165, 'Psalms 69:3', 'Psalms', 69, 3, 'ستومانه شوی یمه زه چې نارې ووهم کومک دپاره زما ستونی دی وچ شوی ستا په انتظار مې سترګې ستړې شوې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms69_verse_3.mp3', '', 1761754199, 1761754199),
(39166, 'Psalms 69:4', 'Psalms', 69, 4, 'چې بې‌سببه رانه کرکه کوي هغوی دي زیات زما د سر له ویښتو دښمنان زما په هکله دروغ وایي دوی دي قوي او غواړي ما ووژني مجبوروي مې دوی ته ورکړمه زه هغه شیان چې ما پټ کړي نه دي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms69_verse_4.mp3', '', 1761754199, 1761754199),
(39167, 'Psalms 69:5', 'Psalms', 69, 5, 'ای خدایه ته ما پېژنې چې زه څومره کم‌عقل یمه ګناهونه زما نه دي پټ له تا نه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms69_verse_5.mp3', '', 1761754199, 1761754199),
(39168, 'Psalms 69:6', 'Psalms', 69, 6, 'ای څښتنه ای مطلق قادره خدایه شرمنده نه دې شي زما په سبب څوک چې په تا باندې توکل کوي ای د اسراییلو خدایه رسوا دې نه شي هغوی زما په خاطر څوک چې تاته کړي رجوع', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms69_verse_6.mp3', '', 1761754199, 1761754199),
(39169, 'Psalms 69:7', 'Psalms', 69, 7, 'ستا په خاطر مې سپکاوی وزغامه او په شرمونو پټ شوم', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms69_verse_7.mp3', '', 1761754199, 1761754199),
