(39173, 'Psalms 69:11', 'Psalms', 69, 11, 'کله چې ما د ویر جامې واغوستې هغوی په ما پورې خندا وکړه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms69_verse_11.mp3', '', 1761754199, 1761754199),
