(39178, 'Psalms 69:16', 'Psalms', 69, 16, 'ای څښتنه ته قبوله مې دعا کړه ځکه تلپاتې مینه ستا غوره ده د خپلې زیاتې همدردۍ نه دې خپل مخ ماته راواړوه!', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms69_verse_16.mp3', '', 1761754199, 1761754199),
(39179, 'Psalms 69:17', 'Psalms', 69, 17, 'د خپل بنده نه دې مخ مه پټوه د ډېر تکلیف سره زه مخ یمه قبوله مې دعا کړه زر', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms69_verse_17.mp3', '', 1761754199, 1761754199),
