(39192, 'Psalms 69:30', 'Psalms', 69, 30, 'په سندرې به د خدای د نوم صفت کومه په شکرونو به یې لویي اعلانومه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms69_verse_30.mp3', '', 1761754199, 1761754199),
(39193, 'Psalms 69:31', 'Psalms', 69, 31, 'دا به خوشحاله کړي څښتن ډېر د هغې نه چې ورته وړاندې شي څاروی ډېر د هغې نه چې د پوره غاښو خوسی شي قرباني ورته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms69_verse_31.mp3', '', 1761754199, 1761754199),
