(39199, 'Leviticus 23:1', 'Leviticus', 23, 1, 'څښتن موسی ته وویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus23_verse_1.mp3', '', 1761754199, 1761754199),
(39200, 'Leviticus 23:2', 'Leviticus', 23, 2, '«د اسراییلو خلکو ته ووایه چې ما ستاسو دپاره څو مذهبي اخترونه ټاکلي دي چې سره راټول شئ او زما عبادت وکړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus23_verse_2.mp3', '', 1761754199, 1761754199),
(39201, 'Leviticus 23:3', 'Leviticus', 23, 3, 'تاسو د خپل کار دپاره شپږ ورځې لرئ، خو اوومه ورځ چې د سبت ورځ ده، د ارام کولو دپاره ده. په هغه ورځ کار مه کوئ، خو د عبادت دپاره راټول شئ. دا مهمه نه ده چې چېرته اوسېږئ، سبت د څښتن ورځ ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus23_verse_3.mp3', '', 1761754199, 1761754199),
(39202, 'Leviticus 23:4', 'Leviticus', 23, 4, 'دغه اخترونه باید په ټاکل شویو وختونو کې اعلان کړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus23_verse_4.mp3', '', 1761754199, 1761754199),
(39203, 'Leviticus 23:5', 'Leviticus', 23, 5, 'څښتن ته د درناوي کولو دپاره د فسحې د اختر لمانځل هر کال د لومړۍ میاشتې په څوارلسمه ورځ د لمرپرېواته په وخت کې پیل کیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus23_verse_5.mp3', '', 1761754199, 1761754199),
(39204, 'Leviticus 23:6', 'Leviticus', 23, 6, 'په پنځلسمه ورځ د فطیرې ډوډۍ اختر پیل کیږي او اووه ورځې دوام کوي. تاسو باید په دې موده کې فطیره ډوډۍ وخورئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus23_verse_6.mp3', '', 1761754199, 1761754199),
(39205, 'Leviticus 23:7', 'Leviticus', 23, 7, 'د دغو ورځو څخه په لومړۍ ورځ د عبادت دپاره سره راټول شئ او هېڅ خپل ورځنی کار مه کوئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus23_verse_7.mp3', '', 1761754199, 1761754199),
(39206, 'Leviticus 23:8', 'Leviticus', 23, 8, 'اووه ورځې هغه نذرانې وړاندې کړئ چې څښتن ته په اور باندې تیاریږي او په اوومه ورځ به بیا د عبادت دپاره سره راټول شئ، خو هېڅ خپل ورځنی کار مه کوئ.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus23_verse_8.mp3', '', 1761754199, 1761754199),
(39207, 'Leviticus 23:9', 'Leviticus', 23, 9, 'څښتن موسی ته وویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus23_verse_9.mp3', '', 1761754199, 1761754199),
(39208, 'Leviticus 23:10', 'Leviticus', 23, 10, '«د اسراییلیانو سره خبرې وکړه او ورته ووایه: کله چې تاسو هغې خاورې ته چې زه یې تاسو ته درکوم ورننوځئ او فصل یې ورېبئ، نو کاهن ته لومړنۍ ګېډۍ ورکړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus23_verse_10.mp3', '', 1761754199, 1761754199),
(39209, 'Leviticus 23:11', 'Leviticus', 23, 11, 'هغه دې دا ګېډۍ د څښتن په حضور کې پورته کړي، ترڅو هغه ستاسو په خاطر قبوله شي. کاهن دې هغه د سبت د ورځې څخه وروسته په بله ورځ پورته کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus23_verse_11.mp3', '', 1761754199, 1761754199),
(39210, 'Leviticus 23:12', 'Leviticus', 23, 12, 'په هماغه ورځ یوه سوځېدونکې نذرانه هم څښتن ته قرباني کړئ، یعنې یو وری چې یو کلن وي او هېڅ عیب په کې نه وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus23_verse_12.mp3', '', 1761754199, 1761754199);